/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerDocumentsRoutes } from './documents.controller.ts';

/** Registers the feature routes. */
export function registerDocumentsModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerDocumentsRoutes(router, services);
}
